// ---------------------------------------------------------------------------
//  Zusammenfassung übernehmen
// ---------------------------------------------------------------------------
//  Modelle liefern trotz klarer Ansage gelegentlich einen Codeblock oder
//  einen einleitenden Satz. Beides wird hier abgeräumt. Lässt sich am Ende
//  kein JSON gewinnen, wird die Rohantwort als Zusammenfassung genommen —
//  eine unformatierte Notiz ist besser als gar keine.

const quelle = $('Signatur prüfen und wegschreiben').first().json.body;
const antwort = $input.first().json;

let ergebnis = null;

if (antwort.statusCode >= 200 && antwort.statusCode < 300) {
  const text = (antwort.body?.content ?? []).map((c) => c.text ?? '').join('').trim();
  const ohneZaun = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const klammer = ohneZaun.slice(ohneZaun.indexOf('{'), ohneZaun.lastIndexOf('}') + 1);

  try {
    ergebnis = JSON.parse(klammer);
  } catch {
    console.warn('Antwort war kein JSON — nehme den Rohtext.');
    ergebnis = { thema: 'Anruf ohne Notiz', zusammenfassung: text.slice(0, 800), dringlichkeit: 3, ergebnis: 'unklar' };
  }
} else {
  console.error(`Anthropic HTTP ${antwort.statusCode}`);
  ergebnis = {
    thema: 'Anruf ohne Notiz',
    zusammenfassung: 'Der Agent hat nichts notiert und die Nachbereitung ist fehlgeschlagen. Die vollständige Abschrift steht in der Datenbank.',
    dringlichkeit: 3,
    ergebnis: 'unklar',
  };
}

const dringlichkeit = Math.min(Math.max(Number(ergebnis.dringlichkeit) || 3, 1), 5);
const wer = ergebnis.name && ergebnis.name !== 'unbekannt' ? ergebnis.name : quelle.anrufer;
const symbol = dringlichkeit >= 4 ? '🔴' : dringlichkeit <= 2 ? '⚪' : '🟠';
const minuten = quelle.dauer_sekunden ? ` · ${Math.max(1, Math.round(quelle.dauer_sekunden / 60))} Min.` : '';

return [{ json: {
  conversation_id: quelle.conversation_id,
  call_id: quelle.call_id,
  zusammenfassung: ergebnis.zusammenfassung,
  meldung: `${symbol} *Anruf von ${wer}*${minuten}\n_${ergebnis.thema}_\n\n${ergebnis.zusammenfassung}\n\n_Nachträglich zusammengefasst — der Agent kam nicht mehr dazu._`,
  dringlichkeit,
} }];
